//! The one binding table: what each guest stub the engine binds crosses to, keyed (library, name). The guest's init binds every interceptable stub through `native_bridge_intercept_symbol(addr, library, name)` (vdso.rs); the libraries are the GL / window proxies (NBS `libnative_bridge_guest_*`: libEGL, libGLESv1_CM, libGLESv2, libGLESv3, libnativewindow), the NDK proxies (libandroid, libandroid_runtime, libjnigraphics: C3) and the guest libc.
//! `table` (generated by build.rs from the NBS stub lists, its binding lists and the EGL/GLES prototypes of two views) gives each (library, name) one entry: `Generic` (a symbol of a host library, through the generic crossing), `Shim` (a hand-written host side, [`shim`]) or `Trap(i)` (a named trap, aborting when called: unbound, or pending a binding class of GS2.2).
//! Every `Generic` symbol is looked up by `dlsym` on its host library's own handle, never `RTLD_DEFAULT`: the global scope can hold another definition of the name (Mesa's own GL exports, libatl_bionic's bionic names next to glibc's).

use std::collections::BTreeMap;
use std::ffi::{CStr, CString, c_void};
use std::sync::Mutex;

use super::unsupported;

mod table {
    include!(concat!(env!("OUT_DIR"), "/bindings_table.rs"));
}

/// The host library a `Generic` entry's symbol is looked up in.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Host {
    /// the host library of the guest proxy's soname in SYSTEM_LIB: the GL fronts (placed by `with_gl_driver`), libandroid and libjnigraphics (the ART root's libraries, host_art.rs `stage_art`)
    System,
    /// the process's bionic provider (`table::PROVIDER_SONAME`, loaded in every ART process): the bionic-only API glibc lacks
    Provider,
    /// glibc's `libc.so.6`
    Glibc,
}

/// What a stub binds to.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Entry {
    /// this symbol of that host library
    Generic(Host, &'static str),
    /// [`shim`] of the stub's name
    Shim,
    /// `table::TRAPS[i]`
    Trap(usize),
}

/// A guest library: its soname (what the guest's init passes to the intercept) and its stubs, in NBS list order.
pub struct Lib {
    pub soname: &'static str,
    pub stubs: &'static [(&'static str, Entry)],
}

/// The thunk pool: one per binding (build.rs: the stub rows and the fixed bindings, rounded to a power of two). The x86 thunks and the QEMU pool (`arch/qemu.rs`) are this size.
pub const THUNKS: usize = table::THUNKS;

/// One row of the table, for gates outside the engine (xtask `gl-proxies`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Binding {
    Generic {
        host: Host,
        symbol: &'static str,
    },
    Shim,
    /// why the stub traps: `unbound: …` (no host side) or `pending: …` (a binding class still to build)
    Trap(&'static str),
}

/// Every (library, stub name, binding) of the table, in table order.
pub fn rows() -> impl Iterator<Item = (&'static str, &'static str, Binding)> {
    table::LIBS.iter().flat_map(|l| {
        l.stubs.iter().map(|&(name, e)| {
            let b = match e {
                Entry::Generic(host, symbol) => Binding::Generic { host, symbol },
                Entry::Shim => Binding::Shim,
                Entry::Trap(i) => Binding::Trap(table::TRAP_NAMES[i].2),
            };
            (l.soname, name, b)
        })
    })
}

/// A trapped stub: calling it aborts, naming the stub and why it is trapped.
extern "C" fn trap<const I: usize>() {
    let (lib, name, why) = table::TRAP_NAMES[I];
    unsupported(&format!(
        "guest stub {lib}:{name} has no host binding ({why})"
    ))
}

/// The hand-written host side of `Entry::Shim` stub `name`: the one match over build.rs `SHIMS` and `NDK_SHIMS` (test `every_shim_has_an_arm`).
fn shim(name: &str) -> Option<usize> {
    Some(match name {
        "pthread_create" => super::intercepts::pthread_create as *const () as usize,
        "pthread_key_create" => super::intercepts::pthread_key_create as *const () as usize,
        "pthread_key_delete" => super::intercepts::pthread_key_delete as *const () as usize,
        "__system_property_foreach" => super::provider::foreach as *const () as usize,
        "__system_property_read_callback" => super::provider::read_callback as *const () as usize,
        #[cfg(not(feature = "qemu-guest"))]
        "sigaction" | "sigaction64" => super::signal::sigaction as *const () as usize,
        "AAssetManager_fromJava" => super::ndk::asset_manager_from_java as *const () as usize,
        "AndroidBitmap_getInfo" => super::ndk::bitmap_get_info as *const () as usize,
        "AndroidBitmap_lockPixels" => super::ndk::bitmap_lock_pixels as *const () as usize,
        "AndroidBitmap_unlockPixels" => super::ndk::bitmap_unlock_pixels as *const () as usize,
        _ => return None,
    })
}

/// What a stub binds to, with its host address (a thunk is made of it by the caller).
pub enum Target {
    Host(usize),
    Trap(usize),
    /// no host symbol: the stub stays unbound
    Absent,
}

impl Target {
    /// The address the stub's thunk crosses to; None when absent.
    pub fn address(self) -> Option<usize> {
        match self {
            Target::Host(a) | Target::Trap(a) => Some(a),
            Target::Absent => None,
        }
    }
}

/// Per library, stubs by outcome: [bound to the host, unbound trap, pending trap, absent], printed once the library's list is complete.
static REPORT: Mutex<BTreeMap<&'static str, [usize; 4]>> = Mutex::new(BTreeMap::new());

#[allow(
    clippy::print_stderr,
    reason = "the startup report: one line per bound library, before any logger"
)]
fn report(lib: &'static Lib, outcome: usize) {
    let Ok(mut r) = REPORT.lock() else { return };
    let c = r.entry(lib.soname).or_insert([0; 4]);
    c[outcome] += 1;
    if c.iter().sum::<usize>() == lib.stubs.len() {
        eprintln!(
            "atl-native-bridge: bindings {}: {} bound to the host, {} unbound (trapped), {} pending a binding class (trapped), {} absent",
            lib.soname, c[0], c[1], c[2], c[3]
        );
    }
}

/// A handle per host library, opened once; 0 = not there.
static HANDLES: Mutex<BTreeMap<String, usize>> = Mutex::new(BTreeMap::new());

/// The handle of `host` for guest library `soname`; None when that host library is not there.
/// A system library is loaded by path from SYSTEM_LIB (the GL fronts are placed there by `with_gl_driver`; the loaded copy is returned when the process already has it, same inode); the provider and glibc are already loaded (`RTLD_NOLOAD`: no constructors run).
fn handle(host: Host, soname: &str) -> Option<usize> {
    let (path, flags) = match host {
        Host::System => (
            format!("{}/{soname}", atl_android_paths::SYSTEM_LIB),
            libc::RTLD_NOW,
        ),
        Host::Provider => (
            table::PROVIDER_SONAME.to_owned(),
            libc::RTLD_NOW | libc::RTLD_NOLOAD,
        ),
        Host::Glibc => ("libc.so.6".to_owned(), libc::RTLD_NOW | libc::RTLD_NOLOAD),
    };
    let mut handles = HANDLES.lock().ok()?;
    if let Some(&h) = handles.get(&path) {
        return (h != 0).then_some(h);
    }
    let c = CString::new(path.clone()).ok()?;
    // SAFETY: dlopen of a host library by path or soname; a front's constructors run here, on the calling host thread.
    let h = unsafe { libc::dlopen(c.as_ptr(), flags) } as usize;
    handles.insert(path, h);
    (h != 0).then_some(h)
}

/// `name` on `host`'s own handle (`soname`: the guest library, naming the front).
fn symbol(host: Host, soname: &str, name: &str) -> Option<usize> {
    let h = handle(host, soname)?;
    let c = CString::new(name).ok()?;
    // SAFETY: dlsym on a live handle with a NUL-terminated name.
    let p = unsafe { libc::dlsym(h as *mut c_void, c.as_ptr()) };
    (!p.is_null()).then_some(p as usize)
}

/// The provider's own `name` (provider.rs shims call through it); None without the provider.
pub fn provider_symbol(name: &CStr) -> Option<usize> {
    symbol(Host::Provider, "", name.to_str().ok()?)
}

/// `name` on the system library `soname` of SYSTEM_LIB (ndk.rs shims call the host side of an NDK function through it); None when that library or symbol is not there.
pub fn system_symbol(soname: &str, name: &str) -> Option<usize> {
    symbol(Host::System, soname, name)
}

/// What `native_bridge_intercept_symbol(_, soname, name)` binds the guest stub to; None when `soname` is not in the table.
pub fn target(soname: &str, name: &str) -> Option<Target> {
    let lib = table::LIBS.iter().find(|l| l.soname == soname)?;
    let entry = lib.stubs.iter().find(|(n, _)| *n == name).map(|&(_, e)| e);
    let found = |a: Option<usize>| match a {
        Some(a) => (Target::Host(a), 0),
        None => (Target::Absent, 3),
    };
    let (t, outcome) = match entry {
        Some(Entry::Generic(host, sym)) => found(symbol(host, lib.soname, sym)),
        Some(Entry::Shim) => found(shim(name)),
        Some(Entry::Trap(i)) => {
            let why = table::TRAP_NAMES[i].2;
            let outcome = if why.starts_with("unbound") { 1 } else { 2 };
            (Target::Trap(table::TRAPS[i] as usize), outcome)
        }
        None => (Target::Absent, 3),
    };
    report(lib, outcome);
    Some(t)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_shim_has_an_arm() {
        for (lib, name, b) in rows() {
            // the QEMU build leaves sigaction unarmed (its signals are QEMU's): the rows bind absent there
            if cfg!(feature = "qemu-guest") && matches!(name, "sigaction" | "sigaction64") {
                continue;
            }
            if b == Binding::Shim {
                assert!(
                    shim(name).is_some(),
                    "{lib}:{name} is a Shim without an arm in bindings::shim"
                );
            }
        }
    }

    #[test]
    fn every_glibc_row_is_glibcs() {
        for (lib, name, b) in rows() {
            if let Binding::Generic {
                host: Host::Glibc,
                symbol: s,
            } = b
            {
                assert!(
                    symbol(Host::Glibc, lib, s).is_some(),
                    "{lib}:{name}: glibc lacks {s}"
                );
            }
        }
    }
}
